#include <stdio.h>
#include <stdlib.h>

typedef struct ListNode {
    int ele;
    struct ListNode *next;
} ListNode;

typedef struct {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList();
void addLast_LinkedList(LinkedList *link, int ele);
int removeFirst_LinkedList(LinkedList* link);

int getResult(int nums[], int m, int n, int tarI, int tarJ);

int main() {
    int m, n;
    scanf("%d %d", &m, &n);

    int nums[m*n];
    for(int i=0; i<m*n; i++) {
        scanf("%d", &nums[i]);
    }

    int tarI, tarJ;
    scanf("%d %d", &tarI, &tarJ);

    printf("%d\n", getResult(nums, m, n, tarI, tarJ));

    return 0;
}

int getResult(int nums[], int m, int n, int tarI, int tarJ) {
    LinkedList* queue = new_LinkedList();

    for(int i=0; i<m; i++) {
        for(int j=0; j<n; j++) {
            if(nums[i * n + j] > 0) {
                addLast_LinkedList(queue, i * n + j);
                break;
            }
        }
    }

    int offsets[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    while(queue->size > 0) {
        int pos = removeFirst_LinkedList(queue);

        int i = pos / n;
        int j = pos % n;

        int x = nums[i * n + j] - 1;

        if(x == 0) break;

        for(int k=0; k<4; k++) {
            int newI = i + offsets[k][0];
            int newJ = j + offsets[k][1];

            if(newI >= 0 && newI < m && newJ >= 0 && newJ < n && nums[newI * n + newJ] == 0) {
                nums[newI * n + newJ] = x;
                addLast_LinkedList(queue, newI * n + newJ);
            }
        }
    }

    return nums[tarI * n + tarJ];
}

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));

    node->ele = ele;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}

int removeFirst_LinkedList(LinkedList* link) {
    if(link->size == 0) exit(-1);

    ListNode* removed = link->head;

    if(link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->head = link->head->next;
    }

    link->size--;

    int res = removed->ele;

    free(removed);

    return res;
}
